#include <stddef.h>

void vectorized_s222(int iterations, int LEN_1D, float *a, float *b, float *c, float *e) {
    if (iterations <= 0 || LEN_1D <= 0) return;

    for (int nl = 0; nl < iterations; nl++) {
        float e_prev = e[0];
        for (int i = 0; i < LEN_1D; i++) {
            float bc = b[i] * c[i];
            a[i] += bc;
            float e_sq = e_prev * e_prev;
            e[i] = e_sq;
            a[i] -= bc;
            e_prev = e_sq;
        }
    }
}

void s222_opt(int iterations, int LEN_1D, float*a,float*b,float*c, float* e)
{
    for (int nl = 0; nl < iterations/2; nl++) {
        for (int i = 1; i < LEN_1D; i++) {
            a[i] += b[i] * c[i];
            a[i] -= b[i] * c[i];
        }
        for (int i = 1; i < LEN_1D; i++) {
            e[i] = e[i - 1] * e[i - 1];
        }
    }
}
